// Generated by AI.
using System;
using GrindHero.Application.Combat;
using GrindHero.Application.Progression;
using GrindHero.Presentation.Definitions;
using GrindHero.Presentation.UI;
using UnityEngine;

namespace GrindHero.Presentation.World
{
    public sealed class SectionAdventure : MonoBehaviour
    {
        [SerializeField] private FirstSectionDefinition definition;
        [SerializeField] private Transform warden;
        [SerializeField] private TextMesh questMarker;
        [SerializeField] private Transform chest;
        [SerializeField] private Transform chestLid;
        [SerializeField] private GameObject treasureGlow;
        [SerializeField] private Transform exit;

        private ISectionSession _session;
        private ICombatSession _combat;
        private HeroActor _hero;
        private HUDPresenter _hud;
        private bool _wasNearWarden;
        private bool _wasNearExit;

        public FirstSectionDefinition Definition => definition;
        public Transform Warden => warden;
        public Transform Chest => chest;
        public bool IsChestOpen => _session != null && _session.IsTreasureLooted(definition.treasureId);
        public string Objective
        {
            get
            {
                if (_session.IsSectionCompleted(definition.sectionId))
                    return "HOLLOW RESTORED  /  Explore or keep growing";
                if (!_session.IsQuestAccepted(definition.questId))
                    return "Speak to the Warden  /  Follow the !";
                if (_session.IsQuestCompleted(definition.questId))
                    return "Walk through the eastern gate";
                return _combat.BossDefeated
                    ? "Guardian defeated  /  Return to the Warden"
                    : "Defeat the Hollow Guardian  /  Eastern ruins";
            }
        }

        public void Initialize(ISectionSession session, ICombatSession combat, HeroActor hero, HUDPresenter hud)
        {
            if (definition == null || warden == null || questMarker == null ||
                chest == null || chestLid == null || treasureGlow == null || exit == null)
            {
                throw new InvalidOperationException("The section is missing story or treasure references.");
            }

            var error = definition.ValidateDefinition();
            if (error != null)
            {
                throw new InvalidOperationException(error);
            }

            _session = session;
            _combat = combat;
            _hero = hero;
            _hud = hud;
            _hud.SetSectionObjective(definition.displayName, Objective);
            RefreshVisuals();
        }

        private void Update()
        {
            if (_session == null)
            {
                return;
            }

            _hud.SetSectionObjective(definition.displayName, Objective);
            RefreshVisuals();
            if (_combat.IsHeroRespawning || Time.deltaTime <= 0f)
            {
                return;
            }

            var nearWarden = IsNear(warden, definition.interactionDistance);
            if (nearWarden && !_wasNearWarden)
            {
                TalkToWarden();
            }

            _wasNearWarden = nearWarden;
            if (IsNear(chest, 1.65f) && !IsChestOpen)
            {
                if (_session.LootTreasure(definition.treasureId, definition.treasureHealthPoints))
                {
                    _hud.ShowMessage(
                        $"GROVE RELIC FOUND\n+{definition.treasureHealthPoints} permanent Health points",
                        new Color(1f, 0.83f, 0.43f), 5f);
                }
            }

            var nearExit = IsNear(exit, 2.2f) &&
                Vector3.Dot(_hero.transform.position - exit.position, exit.forward) >= 0.5f;
            if (nearExit && !_wasNearExit && _combat.BossDefeated &&
                _session.CompleteSection(definition.sectionId))
            {
                _hud.ShowMessage(
                    "MOSSWATCH HOLLOW RESTORED\nThe eastern road is open. Stay and explore; your progress is saved.",
                    new Color(1f, 0.85f, 0.48f), 8f);
            }

            _wasNearExit = nearExit;
        }

        private void TalkToWarden()
        {
            if (!_session.IsQuestAccepted(definition.questId))
            {
                _session.AcceptQuest(definition.questId);
                _hud.ShowMessage(definition.introduction, new Color(1f, 0.89f, 0.66f), 8f);
            }
            else if (_session.ClaimQuestReward(
                         definition.questId, definition.questHealthPoints, definition.questAttackPoints))
            {
                _hud.ShowMessage(
                    $"{definition.conclusion}\n+{definition.questHealthPoints} Health / +{definition.questAttackPoints} Axe Attack",
                    new Color(1f, 0.89f, 0.66f), 8f);
            }
            else
            {
                _hud.ShowMessage(_combat.BossDefeated
                    ? "Warden: The road is yours. The grove still keeps a few secrets."
                    : "Warden: The great guardian waits beside the eastern gate. Follow the lanterns.",
                    new Color(1f, 0.89f, 0.66f), 6f);
            }
        }

        private void RefreshVisuals()
        {
            var complete = _session.IsQuestCompleted(definition.questId);
            questMarker.text = complete ? "" : _combat.BossDefeated ? "?" : "!";
            chestLid.localRotation = Quaternion.Euler(IsChestOpen ? -105f : 0f, 0f, 0f);
            treasureGlow.SetActive(!IsChestOpen);
        }

        private bool IsNear(Transform target, float radius)
        {
            var delta = _hero.transform.position - target.position;
            delta.y = 0f;
            return delta.sqrMagnitude <= radius * radius;
        }
    }
}
